function results = opf_case39_sc(branch_BR_R_7_8, branch_RATE_A_11_12)
    define_constants;
    mpc = loadcase('case39');

    branch_idx_7_8 = find( ...
        (mpc.branch(:, F_BUS) == 7  & mpc.branch(:, T_BUS) == 8) | ...
        (mpc.branch(:, F_BUS) == 8  & mpc.branch(:, T_BUS) == 7) );
    r0_7_8 = mpc.branch(branch_idx_7_8, BR_R);
    assert(all(branch_BR_R_7_8 >= r0_7_8));
    mpc.branch(branch_idx_7_8, BR_R) = branch_BR_R_7_8;

    branch_idx_11_12 = find( ...
        (mpc.branch(:, F_BUS) == 11 & mpc.branch(:, T_BUS) == 12) | ...
        (mpc.branch(:, F_BUS) == 12 & mpc.branch(:, T_BUS) == 11) );
    rate0_11_12 = mpc.branch(branch_idx_11_12, RATE_A);
    assert(all(branch_RATE_A_11_12 <= rate0_11_12));
    mpc.branch(branch_idx_11_12, RATE_A) = branch_RATE_A_11_12;

    mpopt = mpoption('opf.violation', 1e-8, 'model', 'DC');
    baseMVA = mpc.baseMVA;
    ng = size(mpc.gen, 1);

    RUmax_MW = 45;
    R_RU_MW = 70;
    RUmax_pu = RUmax_MW / baseMVA;
    R_RU_pu = R_RU_MW / baseMVA;

    om = opf_setup(mpc, mpopt);
    om.add_var('RU', ng, zeros(ng,1), zeros(ng,1), RUmax_pu*ones(ng,1));

    iPg = om.var.idx.i1.Pg : om.var.idx.iN.Pg;
    iRU = om.var.idx.i1.RU : om.var.idx.iN.RU;
    nv = om.var.N;

    A = sparse(ng, nv);
    A(:, iPg) = speye(ng);
    A(:, iRU) = speye(ng);
    u_pu = mpc.gen(:, PMAX) / baseMVA;
    om.add_lin_constraint('Pg_RU_le_Pmax', A, -inf(ng,1), u_pu);

    Areg = sparse(1, nv);
    Areg(1, iRU) = 1;
    om.add_lin_constraint('region_RU_req', Areg, R_RU_pu, inf(1,1));

    idx_i1 = om.var.idx.i1;
    idx_iN = om.var.idx.iN;

    [x, fval, eflag, ~, ~] = om.solve();

    Va_solution = x(idx_i1.Va:idx_iN.Va);
    Pg_solution = x(idx_i1.Pg:idx_iN.Pg);
    RU_solution = x(iRU) * baseMVA;

    results = mpc;
    results.bus(:, VA) = Va_solution * 180/pi;
    results.gen(:, PG) = Pg_solution;
    results.f = fval;
    results.success = (eflag > 0);

end

