    mpc.branch(branch_idx_6_8, BR_R) = branch_BR_R_6_8;

    rate0_6_8 = mpc.branch(branch_idx_6_8, RATE_A);
    assert(all(branch_RATE_A_6_8 <= rate0_6_8));
    mpc.branch(branch_idx_6_8, RATE_A) = branch_RATE_A_6_8;

    mpopt = mpoption('opf.violation', 1e-7, 'model', 'DC');
    baseMVA = mpc.baseMVA;
    ng = size(mpc.gen, 1);

    SPmax_MW = 45;
    R_SP_MW = 70;
    SPmax_pu = SPmax_MW / baseMVA;
    R_SP_pu = R_SP_MW / baseMVA;

    om = opf_setup(mpc, mpopt);
    om.add_var('SP', ng, zeros(ng,1), zeros(ng,1), SPmax_pu*ones(ng,1));

    iPg = om.var.idx.i1.Pg : om.var.idx.iN.Pg;
    iSP = om.var.idx.i1.SP : om.var.idx.iN.SP;
    nv = om.var.N;

    A = sparse(ng, nv);
    A(:, iPg) = speye(ng);
    A(:, iSP) = speye(ng);
    u_pu = mpc.gen(:, PMAX) / baseMVA;
    om.add_lin_constraint('Pg_SP_le_Pmax', A, -inf(ng,1), u_pu);

    Areg = sparse(1, nv);
    Areg(1, iSP) = 1;
    om.add_lin_constraint('region_SP_req', Areg, R_SP_pu, inf(1,1));

    idx_i1 = om.var.idx.i1;
    idx_iN = om.var.idx.iN;

    [x, fval, eflag, ~, ~] = om.solve();

    Va_solution = x(idx_i1.Va:idx_iN.Va);
    Pg_solution = x(idx_i1.Pg:idx_iN.Pg);

    results = mpc;
    results.bus(:, VA) = Va_solution * 180/pi;
    results.gen(:, PG) = Pg_solution;
    results.f = fval;
    results.success = (eflag > 0);

end

function results = opf_case30_sc(gen_PMAX_1, gen_PMAX_2)
    define_constants;
    mpc = loadcase('case30');

    gen1_idx = find(mpc.gen(:, GEN_BUS) == 1);
    pmax0_gen1 = mpc.gen(gen1_idx, PMAX);
    assert(all(gen_PMAX_1 <= pmax0_gen1));
    mpc.gen(gen1_idx, PMAX) = gen_PMAX_1;

    gen2_idx = find(mpc.gen(:, GEN_BUS) == 2);
    pmax0_gen2 = mpc.gen(gen2_idx, PMAX);
    assert(all(gen_PMAX_2 <= pmax0_gen2));
    mpc.gen(gen2_idx, PMAX) = gen_PMAX_2;

    Pd = sum(mpc.bus(:, PD));
    Pmin = mpc.gen(:, PMIN);
    Pmax = mpc.gen(:, PMAX);
    cost = mpc.gencost(:, 5:7);

    ng = size(mpc.gen, 1);

    H = 2 * diag(cost(:, 1));
    f = cost(:, 2);
    Aeq = ones(1, ng);
    beq = Pd;
    lb = Pmin;
    ub = Pmax;

    Pg = quadprog(H, f, [], [], Aeq, beq, lb, ub);

    results = mpc;
    results.gen(:, PG) = Pg;
    results.f = Pg'*H*Pg/2 + f'*Pg + sum(cost(:,3));
    results.success = 1;

end

function results = opf_case30_sc(bus_PD_7, bus_QD_7, bus_VMIN_8)
    define_constants;
    mpc = loadcase('case30');

    bus7_idx = find(mpc.bus(:, BUS_I) == 7);
    pd0_bus7 = mpc.bus(bus7_idx, PD);
    assert(bus_PD_7 >= pd0_bus7);
    mpc.bus(bus7_idx, PD) = bus_PD_7;

    qd0_bus7 = mpc.bus(bus7_idx, QD);
    assert(bus_QD_7 >= qd0_bus7);
    mpc.bus(bus7_idx, QD) = bus_QD_7;

    bus8_idx = find(mpc.bus(:, BUS_I) == 8);
    vmin0_bus8 = mpc.bus(bus8_idx, VMIN);
    assert(bus_VMIN_8 <= vmin0_bus8);
    mpc.bus(bus8_idx, VMIN) = bus_VMIN_8;

    mpopt = mpoption('opf.violation', 1e-7, 'model', 'AC', 'opf.ac.solver', 'MIPS');

    beta = 5300;
    Vref_target = 1.0;

    om = opf_setup(mpc, mpopt);

    idx_i1 = om.var.idx.i1;
    idx_iN = om.var.idx.iN;
    nb = size(mpc.bus, 1);
    nv = om.var.N;

    Q = sparse(nv, nv);
    Q(idx_i1.Vm:idx_iN.Vm, idx_i1.Vm:idx_iN.Vm) = 2 * beta * speye(nb);

    Vref = Vref_target * ones(nb, 1);
    c = zeros(nv, 1);
    c(idx_i1.Vm:idx_iN.Vm) = -2 * beta * Vref;

    k = beta * sum(Vref.^2);

    om = om.add_quad_cost('voltage_penalty', Q, c, k);

    [x, fval, eflag, ~, ~] = om.solve();

    Vm_solution = x(idx_i1.Vm:idx_iN.Vm);
    Va_solution = x(idx_i1.Va:idx_iN.Va);
    Pg_solution = x(idx_i1.Pg:idx_iN.Pg);
    Qg_solution = x(idx_i1.Qg:idx_iN.Qg);

    results = mpc;
    results.bus(:, VA) = Va_solution * 180/pi;
    results.bus(:, VM) = Vm_solution;
    results.gen(:, PG) = Pg_solution;
    results.gen(:, QG) = Qg_solution;
    results.f = fval;
    results.success = (eflag > 0);

end

function results = opf_case14_sc(branch_BR_R_2_3, branch_RATE_A_4_5)
    define_constants;
    mpc = loadcase('case14');

    branch_idx_2_3 = find( ...
        (mpc.branch(:, F_BUS) == 2 & mpc.branch(:, T_BUS) == 3) | ...
        (mpc.branch(:, F_BUS) == 3 & mpc.branch(:, T_BUS) == 2) );
    r0_2_3 = mpc.branch(branch_idx_2_3, BR_R);
    assert(all(branch_BR_R_2_3 >= r0_2_3));
    mpc.branch(branch_idx_2_3, BR_R) = branch_BR_R_2_3;

    branch_idx_4_5 = find( ...
        (mpc.branch(:, F_BUS) == 4 & mpc.branch(:, T_BUS) == 5) | ...
        (mpc.branch(:, F_BUS) == 5 & mpc.branch(:, T_BUS) == 4) );
    rate0_4_5 = mpc.branch(branch_idx_4_5, RATE_A);
    assert(all(branch_RATE_A_4_5 <= rate0_4_5));
    mpc.branch(branch_idx_4_5, RATE_A) = branch_RATE_A_4_5;

    mpopt = mpoption('opf.violation', 1e-8, 'model', 'DC');

    beta = 11;

    om = opf_setup(mpc, mpopt);

    nb = size(mpc.bus, 1);
    br_on = find(mpc.branch(:, BR_STATUS) == 1);
    nl = length(br_on);

    f = mpc.branch(br_on, F_BUS);
    t = mpc.branch(br_on, T_BUS);

    E = sparse(1:nl, f,  1, nl, nb) + sparse(1:nl, t, -1, nl, nb);

    Q_va = 2 * beta * (E' * E);
    om = om.add_quad_cost('ang_diff_pen', Q_va, [], 0, {'Va'});

    idx_i1 = om.var.idx.i1;
    idx_iN = om.var.idx.iN;

    [x, fval, eflag, ~, ~] = om.solve();

    Va_solution = x(idx_i1.Va:idx_iN.Va);
    Pg_solution = x(idx_i1.Pg:idx_iN.Pg);

    results = mpc;
    results.bus(:, VA) = Va_solution * 180/pi;
    results.gen(:, PG) = Pg_solution;
    results.f = fval;
    results.success = (eflag > 0);

end

